import{_ as t,o as r,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"科学日报 · 2026-10-29（AI 系统架构 / 世界模型 · 规范等变注意力 · 智能体缩放律 · 提示注入防御 · RLVR 崩塌）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/science-daily-2026-10-29-ai.md","filePath":"topics/ai-system-architecture/science-daily-2026-10-29-ai.md"}'),i={name:"topics/ai-system-architecture/science-daily-2026-10-29-ai.md"};function g(e,o,l,a,c,d){return r(),n("div",null,[...o[0]||(o[0]=[s('<h1 id="科学日报-·-2026-10-29-ai-系统架构-世界模型-·-规范等变注意力-·-智能体缩放律-·-提示注入防御-·-rlvr-崩塌" tabindex="-1">科学日报 · 2026-10-29（AI 系统架构 / 世界模型 · 规范等变注意力 · 智能体缩放律 · 提示注入防御 · RLVR 崩塌） <a class="header-anchor" href="#科学日报-·-2026-10-29-ai-系统架构-世界模型-·-规范等变注意力-·-智能体缩放律-·-提示注入防御-·-rlvr-崩塌" aria-label="Permalink to &quot;科学日报 · 2026-10-29（AI 系统架构 / 世界模型 · 规范等变注意力 · 智能体缩放律 · 提示注入防御 · RLVR 崩塌）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-29.md</code> — 第48期 ｜ AI 板块（5 篇 arXiv） 落盘说明：文件名带 <code>-ai</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-29-ai-·-1-5-thinkworld-——-把「动作思维」写成动力学链-再用世界想象做强化" tabindex="-1">科学日报 2026-10-29（AI · 1/5）：ThinkWorld —— 把「动作思维」写成动力学链，再用世界想象做强化 <a class="header-anchor" href="#科学日报-2026-10-29-ai-·-1-5-thinkworld-——-把「动作思维」写成动力学链-再用世界想象做强化" aria-label="Permalink to &quot;科学日报 2026-10-29（AI · 1/5）：ThinkWorld —— 把「动作思维」写成动力学链，再用世界想象做强化&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-29.md</code> ｜ arXiv: 2610.37666 ｜ cs.RO/cs.AI (2026-10-28)</p></blockquote><ul><li>问题：视觉-语言-动作（VLA）模型泛化受限于<strong>带动作标注的机器人演示</strong>的多样性与覆盖度；人类视频行为与环境经验更广，从中学习却面临「<strong>可扩展数据 vs 显式动作接地</strong>」的根本权衡。</li><li>方法：<strong>ThinkWorld</strong> 把动作推理<strong>扎根于世界动力学</strong>，用<strong>世界想象 + 强化学习</strong>加以强化。它把每个动作思维表示为<strong>动力学链（Chain-of-Dynamics, CoD）</strong>——一串<strong>离散运动 token</strong>，刻画连接「当前世界」与「未来状态」的中间动力学，并作为<strong>跨本体的共同动作表示</strong>。做法：先用<strong>带动作标注演示</strong>初始化 CoD，再<strong>预测每个 CoD 诱导的未来</strong>、<strong>强化那些预测更贴合观测结果的 CoD</strong>。</li><li>结果：<strong>无动作标注的视频</strong>也能通过观测到的状态转移提供直接监督，让<strong>人类与机器人经验在同一推理空间互相精炼</strong>；仿真与真机实验显示有效的人→机迁移、以及对未见任务/环境的强泛化。</li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>ai-brain</code>）： <ol><li><strong>「把『动作』抽象成跨本体可共享的中间表示」＝统一监督空间的钥匙</strong> —— 动作 token 是<strong>本体特异的</strong>（人手 vs 夹爪），而<strong>动力学（状态转移）是跨本体共享的</strong>；把思维建在动力学上，才能用人类视频监督机器人策略。判据：<strong>当两个来源的数据「观测不同、规律相同」时，把学习目标从「现象」上移到「共享规律」，就能把弱标注数据接进训练。</strong> 这与 10-25 EM 波隐含推理、10-28「在共享上下文里联合评判使估计可比」同族——<strong>换共享参照系 &gt; 各自独立建模。</strong></li><li><strong>「用世界模型的预测误差当奖励」＝无需动作标签的自监督</strong> —— 强化的是「预测未来更准的 CoD」，而不是模仿单一动作。可迁移判据：<strong>当缺乏显式标签但有可观测的后续状态时，用「预测后续状态是否命中」作为学习信号。</strong></li><li><strong>一句话定位</strong>：这是「<strong>世界模型 + 推理链</strong>」在机器人泛化上的落地，把 10-28 EBench 的「MLLM 直接控制 vs 带策略脚手架」推进到<strong>统一动作表示</strong>层面。</li></ol></li></ul><hr><h2 id="科学日报-2026-10-29-ai-·-2-5-把注意力看作格点规范场论-——-关系只能通过-wilson-环相互作用" tabindex="-1">科学日报 2026-10-29（AI · 2/5）：把注意力看作格点规范场论 —— 关系只能通过 Wilson 环相互作用 <a class="header-anchor" href="#科学日报-2026-10-29-ai-·-2-5-把注意力看作格点规范场论-——-关系只能通过-wilson-环相互作用" aria-label="Permalink to &quot;科学日报 2026-10-29（AI · 2/5）：把注意力看作格点规范场论 —— 关系只能通过 Wilson 环相互作用&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-29.md</code> ｜ arXiv: 2610.37656 ｜ cs.LG (2026-10-28)</p></blockquote><ul><li>问题：关系通过<strong>共享实体复合</strong>（Alice 是 Bob 的母亲、Bob 是 Carol 的父亲 ⟹ Alice 是 Carol 的祖母），<strong>顺序重要</strong>（父亲的母亲 ≠ 母亲的父亲），而验证一个复合关系等价于<strong>闭合一个回路</strong>。</li><li>方法：作者证明——若每个实体的<strong>坐标框架可独立旋转</strong>（逐实体规范自由），则三件事必然成立：① 在纯规范区，<strong>不共享任何环的关系根本无法相互作用</strong>；② 三角形的唯一规范不变分数是其<strong>和乐（holonomy）H = T_ij T_jk T_ki 的类函数</strong>，即一个 <strong>Wilson 环</strong>；③ 边的唯一等变更新形式是 <strong>U = Ψ(H)·T_ij</strong>（Ψ 共轭等变）。于是「<strong>用 Wilson 环做边注意力</strong>」<strong>不是众多设计之一，而是对称性唯一允许的形式</strong>。</li><li>结果（实测）： <ul><li>在一般关系图上实例化这一等变子族（holonomy attention）：<strong>零训练、仅靠复合</strong>，在 <strong>1/5 边被污染</strong>的稀疏图上以 <strong>0.88</strong> 推断出未观测的 <strong>S₄ 关系</strong>（与专门的同步算法相当或略低），而<strong>所有交换架构被卡在 0.083</strong>；</li><li>其<strong>和乐分数以 AUC 0.99 标记被污染的三角形</strong>（交换分数被第二条选择规则卡在 0.76），并能<strong>无标签聚类</strong>；</li><li>三套社群各执一块：知识图谱的<strong>交换算子嵌入</strong> = 其<strong>阿贝尔区</strong>；<strong>AlphaFold 的三角更新</strong>与 <strong>Edge Transformer</strong> 有其<strong>形状</strong>（边经第三顶点更新）却缺<strong>约束</strong>；<strong>格点 QCD</strong> 则在格上等变地构造它。</li></ul></li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>quantum-physics</code>）： <ol><li><strong>「对称性把设计空间砍到只剩一个形式」＝第一性原理式架构设计</strong> —— 不是「试了很多注意力变体发现三角更新更好」，而是<strong>证明在外加规范自由下，Wilson 环是唯一等变答案</strong>。判据：<strong>当你想在架构里加一个归纳偏置时，先问『在什么对称性约束下，它是唯一解』——若是唯一解，就不用调参去发现它。</strong> 这与 10-25 莫尔「粒子—空穴对称性破缺是可设计自由度」、10-23 反铁磁「对称性判死的效应被八极矩救活」同构——<strong>对称性/守恒量是设计的坐标系。</strong></li><li><strong>「零训练就能复合关系」＝把能力外包给结构，而非参数</strong> —— 0.88 的推断力<strong>全部来自等变构造本身</strong>，交换架构上限 0.083。可迁移判据：<strong>当任务本质是「关系代数」时，先造一个满足关系复合的结构，而不是让参数去学复合律。</strong></li><li><strong>一句话定位</strong>：本条把「关系注意力」与 QCD 的<strong>规范场论</strong>统一——是「<strong>AI 架构 ↔ 物理学</strong>」的又一次深层同构（本库 <code>ai-brain</code> 的跨域母题）。</li></ol></li></ul><hr><h2 id="科学日报-2026-10-29-ai-·-3-5-工具使用智能体的缩放律-——-扩「工具-数据库多样性」比堆任务数更值" tabindex="-1">科学日报 2026-10-29（AI · 3/5）：工具使用智能体的缩放律 —— 扩「工具/数据库多样性」比堆任务数更值 <a class="header-anchor" href="#科学日报-2026-10-29-ai-·-3-5-工具使用智能体的缩放律-——-扩「工具-数据库多样性」比堆任务数更值" aria-label="Permalink to &quot;科学日报 2026-10-29（AI · 3/5）：工具使用智能体的缩放律 —— 扩「工具/数据库多样性」比堆任务数更值&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-29.md</code> ｜ arXiv: 2610.37648 ｜ cs.AI/cs.LG (2026-10-28)</p></blockquote><ul><li>问题：要训出能完成复杂多步任务的大模型<strong>工具使用智能体</strong>，关键之一：<strong>合成生成环境里的数据组成</strong>如何影响训练效果？</li><li>方法：提出 <strong>SynthAPI 流水线</strong>，沿<strong>工具、任务、数据库</strong>三轴<strong>显式控制</strong>所生成环境的多样性；在 <strong>849 个模型（四种规模）、458,752 个任务</strong>上系统扫过生成参数。</li><li>结果：推导出一条<strong>缩放律</strong>——可由<strong>合成环境的规模与组成预测下游工具使用智能体的泛化</strong>。可预测关系给出几条经验：随数据预算增长，<strong>扩展「工具多样性」与「数据库多样性」比增加任务数更有效</strong>，而<strong>提高数据复杂度收益更大</strong>；按此缩放得到的智能体在<strong>四个评测基准</strong>上超过用既往工作数据训练的模型。</li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>ai-brain</code>）： <ol><li><strong>「多样性维度上，选对轴比加量更有效」</strong> —— 数据预算增长时，<strong>扩工具/数据库多样性 &gt; 扩任务数</strong>。判据：<strong>当你在扩数据时，先问『哪一轴的多样性还没被覆盖』，而不是先把已有类型的问题数量翻倍。</strong> 这与 10-28 DecisionRAG「先组织再检索」、10-27「把复杂度从深层光路挪到测量端」同族——<strong>分配/维度 &gt; 数量。</strong></li><li><strong>「合成环境可控 = 缩放律可测」</strong> —— 能推导缩放律的前提是<strong>环境生成有显式旋钮</strong>（工具/任务/数据库三轴）。可迁移判据：<strong>要研究『数据如何影响能力』，先让数据生成有可扫的轴，而不是用一个黑箱数据集。</strong></li><li><strong>一句话定位</strong>：这是<strong>工具使用智能体</strong>领域的第一条系统缩放律，把「数据怎么造」从经验直觉升级为<strong>可预测的规律</strong>。</li></ol></li></ul><hr><h2 id="科学日报-2026-10-29-ai-·-4-5-heads-of-security-——-用「可学习注意力门」做指令—数据分离-抗提示注入" tabindex="-1">科学日报 2026-10-29（AI · 4/5）：Heads of Security —— 用「可学习注意力门」做指令—数据分离，抗提示注入 <a class="header-anchor" href="#科学日报-2026-10-29-ai-·-4-5-heads-of-security-——-用「可学习注意力门」做指令—数据分离-抗提示注入" aria-label="Permalink to &quot;科学日报 2026-10-29（AI · 4/5）：Heads of Security —— 用「可学习注意力门」做指令—数据分离，抗提示注入&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-29.md</code> ｜ arXiv: 2610.37657 ｜ cs.CR/cs.AI (2026-10-28)</p></blockquote><ul><li>问题：<strong>提示注入（prompt injection）<strong>是 LLM 智能体落地的核心安全威胁——不可信内容里夹带指令会被模型</strong>当作命令执行</strong>。</li><li>方法：<strong>HoS（Heads of Security）<strong>用</strong>少量可学习的「逐头注意力门」（per-head attention gates）<strong>来强制</strong>指令—数据分离</strong>：它学习<strong>每个注意力头应如何在「可信 token」与「不可信 token」之间重新分配注意力</strong>，让模型能<strong>推理</strong>不可信内容而<strong>不执行</strong>其中的注入指令。对照 <strong>SecAlign++</strong>（微调）与 <strong>ASIDE</strong>（同样把指令—数据分离做进架构）。</li><li>结果（实测）： <ul><li>黑盒 <strong>RL-Hammer</strong> 攻击对 GPT-OSS-20B 的 <strong>ASR 达 97%</strong>、对 SecAlign 85%，<strong>对 HoS 只有 10%</strong>；</li><li>白盒 <strong>Claudini</strong> 经 autoresearch 强化后，要让 HoS 达到同样 ASR 需<strong>多 3 倍 FLOPs</strong>；</li><li>HoS 在 <strong>few-shot</strong> 设置下仍保持<strong>基座效用</strong>（SecAlign/ASIDE 会退化）；带静态攻击的智能体基准上 HoS 与 SecAlign 相近，而 ASIDE 因工具使用差只到 <strong>10% 效用</strong>。</li></ul></li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>ai-brain</code>）： <ol><li><strong>「把安全做进注意力分配，而不是做进权重」</strong> —— 微调（SecAlign）改的是<strong>参数</strong>，HoS 改的是<strong>每步注意力的信任来源分配</strong>。判据：<strong>当一类错误的根源是「信息源混在一起」时，先想着把来源在架构层面分开（选择性注意），而不是重训权重去记住防御模式。</strong> 这与 10-28「企业 RAG 把本体放到工件层、使跨服务竞争规则结构性缺席」同族——<strong>结构分层 &gt; 事后过滤。</strong> 也与本期物理「换路径 &gt; 加力度」共振。</li><li><strong>「few-shot 不损效用」是关键卖点</strong> —— 常见防御（SecAlign/ASIDE）在低资源下<strong>用能力换安全</strong>，HoS 不换。可迁移判据：<strong>评估一个安全机制时，必须同时报『防住了多少』与『花了多少效用』——只在一条轴上好看不算好。</strong></li><li><strong>一句话定位</strong>：给出了一条<strong>架构级、低成本、抗自适应攻击</strong>的注入防御路径。</li></ol></li></ul><hr><h2 id="科学日报-2026-10-29-ai-·-5-5-无标签-rlvr-为何崩塌-——-跨任务耦合驱动的「集体不稳定性」" tabindex="-1">科学日报 2026-10-29（AI · 5/5）：无标签 RLVR 为何崩塌 —— 跨任务耦合驱动的「集体不稳定性」 <a class="header-anchor" href="#科学日报-2026-10-29-ai-·-5-5-无标签-rlvr-为何崩塌-——-跨任务耦合驱动的「集体不稳定性」" aria-label="Permalink to &quot;科学日报 2026-10-29（AI · 5/5）：无标签 RLVR 为何崩塌 —— 跨任务耦合驱动的「集体不稳定性」&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-29.md</code> ｜ arXiv: 2610.37553 ｜ cs.LG (2026-10-28)</p></blockquote><ul><li>问题：用<strong>可验证奖励</strong>做<strong>无标签</strong> RLVR 时，奖励模型「与自己多数投票一致」：起初提升推理，但<strong>最终崩塌</strong>——<strong>自评奖励升到 1，而准确率下降</strong>，甚至对所有问题给出<strong>同一个答案</strong>；且这种崩塌<strong>只在训练使用很多问题时出现</strong>。</li><li>方法：把这种「依赖数据集规模」解释为一种<strong>集体不稳定性</strong>——在问题<strong>共享参数</strong>的可解多问题模型中，只要单问题自强化漂移 F 的<strong>群体平均斜率 ⟨F&#39;⟩ 为正</strong>，群体就会<strong>放大任何共享扰动</strong>。</li><li>结果（实测/理论）： <ul><li>机制是两种速度的竞赛：<strong>单问题锐化被 1/N 拖慢</strong>，而<strong>共享模以 ∝λ² 增长、与 N 无关</strong>（λ 为共享耦合强度）→ 出现<strong>临界问题数 N_c ≈ ln(1/δ)/(λ²G)</strong>；</li><li>模拟验证：尖锐相变、<strong>N_c ∝ λ⁻²</strong>（至多对数修正）、跨耦合/置信剖面/训练变体的<strong>单一临界放大 λ²NG</strong>、对批大小的<strong>对数依赖</strong>、<strong>初始模型自信时不崩塌</strong>；</li><li>核版理论识别出一个<strong>保护性耦合</strong>（锐化的推广）与一个<strong>稳定均匀集体模的边缘熵 bonus</strong>；</li><li>小 Transformer 的无标签 RL 中：<strong>去掉共享方向完全避免崩塌</strong>，恢复它则崩塌重现，且崩塌随<strong>训练集规模与基座模型熵</strong>增长。</li></ul></li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>ai-brain</code>）： <ol><li><strong>「崩塌是集体动力学问题，不是训练 bug」</strong> —— 单个问题上的自强化只会慢慢锐化（被 1/N 拖慢），<strong>真正致命的是跨任务共享的那个模</strong>（∝λ²，与 N 无关）。判据：<strong>当一个自监督/自奖励系统随规模变大而变差时，先找「跨样本共享的耦合方向」，而不是怀疑某个样本有毒。</strong> 这与 10-28「估计量方差本身影响训练」「EM 波隐含推理」同族——<strong>群体层面的耦合方向是独立于单样本质量的失效源。</strong></li><li><strong>「相变式的临界规模可预测」</strong> —— N_c ≈ ln(1/δ)/(λ²G) 给出<strong>何时会崩</strong>的先验公式。可迁移判据：<strong>用一条可由耦合强度估计的临界规模，提前决定「能不能上这种自奖励训练」。</strong></li><li><strong>一句话定位</strong>：为「无标签自奖励 RL」提供了<strong>可诊断、可拆解（删掉共享方向）<strong>的失效理论——与 10-28 GRPO 弱验证器审计构成</strong>同一母题的两面：自奖励系统的可信度管理</strong>（一个管「作弊」，一个管「集体崩塌」）。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/ai-system-architecture/index.md</code> ｜ <code>topics/ai-brain/index.md</code> ｜ 第48期 AI 板块</p></blockquote><p>关键词：科学日报第48期、ThinkWorld、2610.37666、动力学链 Chain-of-Dynamics、CoD、离散运动 token、世界想象 world imagination、VLA 泛化、人→机迁移、跨本体共享动作表示、预测未来当奖励、Attention as Lattice Gauge Theory、2610.37656、Wilson 环、holonomy、和乐、逐实体规范自由、等变 U=Ψ(H)T、训练自由推断 S4 关系 0.88、交换架构上限 0.083、污染三角 AUC 0.99、AlphaFold 三角更新、Edge Transformer、格点 QCD、对称性唯一解、SynthAPI、2610.37648、工具使用智能体缩放律、849 模型、458752 任务、工具多样性、数据库多样性、任务数、数据复杂度、四个基准、Heads of Security、HoS、2610.37657、逐头注意力门 per-head attention gates、指令数据分离、RL-Hammer ASR 97%、SecAlign 85%、HoS 10%、Claudini 3 倍 FLOPs、few-shot 保基座效用、ASIDE、安全做进注意力分配、Collective Dynamics of Self-Reinforcement、2610.37553、无标签 RLVR 崩塌、跨任务耦合、⟨F&#39;⟩&gt;0、共享模 ∝λ²、临界问题数 N_c=ln(1/δ)/(λ²G)、尖锐相变、λ²NG 临界放大、保护性耦合、边缘熵 bonus、去掉共享方向避免崩塌、集体不稳定性、自奖励可信度管理</p><p>关联：<code>topics/ai-system-architecture/index.md</code>、<code>topics/ai-system-architecture/science-daily-2026-10-28-ai.md</code>（DecisionRAG/简单脚手架/GRPO 审计/EBench/EvoRouter）、<code>topics/ai-system-architecture/science-daily-2026-10-27-ai.md</code>（企业RAG/OPST/单纯形/TopKLoRA）、<code>topics/ai-brain/index.md</code>、<code>topics/quantum-physics/science-daily-2026-10-29-quantum.md</code></p>',26)])])}const m=t(i,[["render",g]]);export{h as __pageData,m as default};
